return {rwnpc01={id="rwnpc01",dsc="官府弟子，凌云的兄长，和明宗宝、齐天关系十分要好。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc02={id="rwnpc02",dsc="看打扮似乎是少林弟子。",sex="男",age=25,looks=20,showequip={},withCorpse=0},rwnpc03={id="rwnpc03",dsc="看打扮似乎是全真弟子。",sex="男",age=25,looks=20,showequip={},withCorpse=0},rwnpc04={id="rwnpc04",dsc="看打扮似乎是丐帮弟子。",sex="男",age=25,looks=20,showequip={},withCorpse=0},rwnpc05={id="rwnpc05",dsc="看打扮似乎是峨眉弟子。",sex="女",age=25,looks=20,showequip={},withCorpse=0},rwnpc06={id="rwnpc06",dsc="看打扮似乎是武当弟子。",sex="男",age=25,looks=20,showequip={},withCorpse=0},rwnpc07={id="rwnpc07",dsc="官府弟子，凌风的兄弟，平日虽有些骄横，但平日秉公办案，深得大人喜爱。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc08={id="rwnpc08",dsc="她是慕容业的婢女谢小雅，她生的娇美俏丽，十分可人。",sex="女",age=20,looks=25,showequip={},withCorpse=0},rwnpc09={id="rwnpc09",dsc="她便是这一代的万灵谷主丁红蝶，她身穿粉红纱裙，美艳不可方物，手脚都穿戴着金银饰器，稍一活动，金银就发出的清脆的碰撞声音，十分好听。",sex="女",age=17,looks=26,showequip={},withCorpse=0},rwnpc10={id="rwnpc10",dsc="重光教的右神使。创教师祖之后。她穿着一件淡青色轻罗裙，因身材娇小而显得袖口有些宽大。看起来年纪小小，梳着一个双平鬟，些许云鬓垂在两耳旁，小脸微圆，皓齿明眸，笑起来甜美动人。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},rwnpc11={id="rwnpc11",dsc="看打扮似乎是重光教徒。",sex="男",age=25,looks=20,showequip={},withCorpse=0},rwnpc12={id="rwnpc12",dsc="他是莫天雄的大弟子。",sex="男",age=25,looks=24,showequip={},withCorpse=0},rwnpc13={id="rwnpc13",dsc="这是昆仑派弟子温笑笑，整天就喜欢玩耍，不爱干正事。",sex="男",age=20,looks=23,showequip={},withCorpse=0},rwnpc14={id="rwnpc14",dsc="落月山庄的一名弟子。目若秋水，风度翩翩，笑容让人捉摸不定。",sex="男",age=20,looks=23,showequip={},withCorpse=0},rwnpc15={id="rwnpc15",dsc="他是俞建州游历江湖时收下的徒弟，天资颇佳。",sex="男",age=20,looks=22,showequip={},withCorpse=0},rwnpc16={id="rwnpc16",dsc="唐不平的次女。性格泼辣活泼，与兄长一同闯荡江湖，让唐元枫十分宠爱又头疼不已的妹妹。",sex="女",age=18,looks=25,showequip={},withCorpse=0},rwnpc17={id="rwnpc17",dsc="他便是捕风神探燕天云，朝廷成立捕风卫，便是由他主管，陆千侯的得力干将之一。",sex="男",age=37,looks=20,showequip={},withCorpse=0},rwnpc18={id="rwnpc18",dsc="这是伏龙的弟子秦冬初，性烈如火，经常与人争斗。",sex="男",age=26,looks=18,showequip={},withCorpse=0},rwnpc19={id="rwnpc19",dsc="这是海鲸的弟子左泽清，为帮中事务常在外奔走。",sex="男",age=25,looks=20,showequip={},withCorpse=0},rwnpc20={id="rwnpc20",dsc="盗墓世家临淄夏侯之后。本名夏侯燕，幼时崇拜盗圣惊鸿雁的传说，自称为惊鸿燕。喜好盗墓，且技艺高超，所到之处寸草不生。",sex="女",age=18,looks=21,showequip={},withCorpse=0},rwnpc21={id="rwnpc21",dsc="他是财神帮的弟子廉英，武功不算出彩，但是经商之才。",sex="男",age=25,looks=20,showequip={},withCorpse=0},rwnpc22={id="rwnpc22",dsc="这是天狼的弟子夏秋蝉，天资卓越，向来是心高气傲。",sex="女",age=17,looks=24,showequip={},withCorpse=0},rwnpc23={id="rwnpc23",dsc="皇帝最宠爱的小女儿，与福王平王一起长大，喜欢舞刀弄枪。",sex="女",age=20,looks=27,showequip={},withCorpse=0},rwnpc24={id="rwnpc24",dsc="她衣着显贵，是贵家之女，怀抱一只金眸玄猫，和平遥公主关系极好。",sex="女",age=19,looks=28,showequip={},withCorpse=0},rwnpc25={id="rwnpc25",dsc="他垂着腰背，微微低着头，一手却邪剑法使得炉火纯青，宫里侍卫都尊称他为徐公公。",sex="男",age=55,looks=22,showequip={},withCorpse=0},rwnpc26={id="rwnpc26",dsc="他慈祥可亲，须发皆白。身穿青袍，举手投足间给人一种无尽的神秘之感。",sex="男",age=60,looks=15,showequip={},withCorpse=0},rwnpc27={id="rwnpc27",dsc="她是上官林之女，财神帮帮主。她智慧绝伦，以女流之躯经营庞大的财神帮，并开始开拓海外贸易。好收集奇珍异宝，富可敌国。武功习自其父，虽身手了得，但凡事都喜欢用金钱来解决，不喜动武。",sex="女",age=23,looks=26,showequip={},withCorpse=0},rwnpc28={id="rwnpc28",dsc="萧逸龙次子。曾为报仇，与其父独上拜日教，火烧朱雀堂，一战少年成名，年纪轻轻便在剑术上颇有成就。生性好斗，不肯屈居人下，与其父淡然不争恰是截然不同。",sex="男",age=36,looks=25,showequip={},withCorpse=0},rwnpc29={id="rwnpc29",dsc="她是天竞门的第六代掌门。她素日鲜少在门中露面，多半辗转于各大戏楼，且为了唱戏方便，面上常带着花旦妆。她虽醉心戏乐，武功却也让人佩服，传闻昔日她曾与江上游一战，后三掌为盟，与丐帮定下互不相犯之规。故，凡市井之地只知“百花杀”，不知“杨秋白”，凡江湖之处只知“杨秋白”，不知“百花杀”。",sex="女",age=42,looks=26,showequip={},withCorpse=0},rwnpc30={id="rwnpc30",dsc="陆千侯年少时以一手八臂哪吒戟法成名与江湖，而后投身朝廷，身任刑部要职二十余载，所破大案要案无数，天子御封其为千军侯，统领京诸卫。",sex="男",age=50,looks=26,showequip={},withCorpse=0},rwnpc31={id="rwnpc31",dsc="他鹤发松姿，身穿黑袍，举手投足风风火火。",sex="男",age=60,looks=15,showequip={},withCorpse=0},rwnpc32={id="rwnpc32",dsc="一个专卖桂花板栗糕的小贩。",sex="男",age=45,looks=17,showequip={},withCorpse=0},rwnpc33={id="rwnpc33",dsc="一个专门制作葱包桧的小贩。",sex="男",age=45,looks=17,showequip={},withCorpse=0},rwnpc34={id="rwnpc34",dsc="一个专门制作西湖藕粉的小贩。",sex="男",age=45,looks=17,showequip={},withCorpse=0},rwnpc35={id="rwnpc35",dsc="一个专门制作麻球的小贩。",sex="男",age=45,looks=17,showequip={},withCorpse=0},rwnpc36={id="rwnpc36",dsc="他是个落魄剑客，身边除了一把剑再无其他。",sex="男",age=45,looks=17,showequip={},withCorpse=0},rwnpc37={id="rwnpc37",dsc="手中牵着一匹驮马。",sex="男",age=33,looks=18,showequip={},withCorpse=0},rwnpc38={id="rwnpc38",dsc="来自苗疆的卖艺人，身着奇装异服，戴着银首饰，手中把玩着一条红色的毒蛇。",sex="男",age=33,looks=17,showequip={},withCorpse=0},rwnpc39={id="rwnpc39",dsc="正在围观卖艺的表演。",sex="男",age=22,looks=17,showequip={},withCorpse=0},rwnpc40={id="rwnpc40",dsc="正在大吃大喝的和尚。满嘴都是油光。",sex="男",age=22,looks=18,showequip={},withCorpse=0},rwnpc41={id="rwnpc41",dsc="从京城游历至此的书生。",sex="男",age=22,looks=21,showequip={},withCorpse=0},rwnpc42={id="rwnpc42",dsc="他坐在轿子里，撩开帘子看向外面。这人眉目如画，青丝如瀑，搭在帘子上的手指白皙修长，戴着一枚白玉戒指。",sex="男",age=21,looks=24,showequip={},withCorpse=0},rwnpc43={id="rwnpc43",dsc="白衣男子轿子旁的护卫。",sex="男",age=21,looks=21,showequip={},withCorpse=0},rwnpc44={id="rwnpc44",dsc="她一身侠女打扮，身后背着小小包袱，虽然用斗笠遮住了脸，但露出的部位依旧可以看出是一名十足的美人。",sex="女",age=19,looks=24,showequip={},withCorpse=0},rwnpc45={id="rwnpc45",dsc="一名风度翩翩的公子，手摇折扇漫步而行。",sex="男",age=22,looks=21,showequip={},withCorpse=0},rwnpc46={id="rwnpc46",dsc="一名千金小姐，跟在赵公子身旁。",sex="女",age=11,looks=22,showequip={},withCorpse=0},rwnpc47={id="rwnpc47",dsc="他是侍奉在平遥公主身边的公公。",sex="男",age=55,looks=22,showequip={},withCorpse=0},rwnpc48={id="rwnpc48",dsc="他手持折扇，满腹经纶的书生气，却又带了一丝洒脱的侠气。",sex="男",age=36,looks=25,showequip={},withCorpse=0},rwnpc49={id="rwnpc49",dsc="他据传是来自军中，后做了平遥公主的门客，习得一身刚强的拳法，为人亦是豪爽。",sex="男",age=45,looks=20,showequip={},withCorpse=0},rwnpc50={id="rwnpc50",dsc="她生得曼妙，一举一动皆婀娜妩媚，据传出身自烟柳之地，但一支玉笛柔曲藏杀意，一手掌法棉里裹刀剑，武艺不低于江湖中的高手。",sex="女",age=27,looks=26,showequip={},withCorpse=0},rwnpc51={id="rwnpc51",dsc="他素来少言寡语，即使对着平遥公主也不曾多言两字，是以也无人能知他出生何处，只知他一手刀法出神入化。",sex="男",age=30,looks=25,showequip={},withCorpse=0},["25rwnpc1"]={id="25rwnpc1",dsc="他一身云锦官袍，手持长枪，曾是一名驻边将领，卸甲后入官府任长老。",sex="男",age=50,looks=20,showequip={},withCorpse=0},["25rwnpc2"]={id="25rwnpc2",dsc="他手持长剑，一身道袍一尘不染，面容清癯，眼神平和如渊，是武当派的一位长老。",sex="男",age=48,looks=21,showequip={},withCorpse=0},["25rwnpc3"]={id="25rwnpc3",dsc="看打扮似乎是官府弟子。",sex="男",age=23,looks=17,showequip={},withCorpse=0},["25rwnpc4"]={id="25rwnpc4",dsc="看打扮似乎是武当弟子。",sex="男",age=24,looks=17,showequip={},withCorpse=0},["25rwnpc5"]={id="25rwnpc5",dsc="皇帝最宠爱的小女儿，与福王平王一起长大，喜欢舞刀弄枪。",sex="女",age=20,looks=27,showequip={},withCorpse=0},["25rwnpc6"]={id="25rwnpc6",dsc="他头戴方巾，身着长衫，曾是江南有名的才子，因厌倦科举仕途，便做了公主的门客。",sex="男",age=29,looks=21,showequip={},withCorpse=0},["25rwnpc7"]={id="25rwnpc7",dsc="她蒙着面，看不清具体面容，仅露出一双灵动的双眼，带着一股贵气，似曾相识。",sex="女",age=20,looks=27,showequip={},withCorpse=0},["25rwnpc8"]={id="25rwnpc8",dsc="他是曾是书院编修，后因文采出众得公主赏识，被公主收做门客。",sex="男",age=30,looks=20,showequip={},withCorpse=0},["25rwnpc9"]={id="25rwnpc9",dsc="他腰边常挂着葫芦，留着半尺长的胡须，一身沾着酒渍的短褂，嗜酒如命，但眼中透着清明，一行一动间好似透着一股妙劲。",sex="男",age=45,looks=18,showequip={},withCorpse=0},["25rwnpc10"]={id="25rwnpc10",dsc="一个约摸十岁的小童，摇头晃脑，老神在在，倒是有几番有趣。",sex="男",age=10,looks=20,showequip={},withCorpse=0},["25rwnpc11"]={id="25rwnpc11",dsc="一个卖着各种杂货的小贩。",sex="男",age=45,looks=17,showequip={},withCorpse=0},["25rwnpc12"]={id="25rwnpc12",dsc="他是侍奉在平遥公主身边的护卫。",sex="男",age=35,looks=18,showequip={},withCorpse=0},["25rwnpc13"]={id="25rwnpc13",dsc="他穿着朴素的麻布衣，手上布满老茧与细小的划痕，据传是出生于灯彩世家，一手做长明灯的手法出神入化。",sex="男",age=50,looks=20,showequip={},withCorpse=0},["25rwnpc14"]={id="25rwnpc14",dsc="他穿着朴素的麻布衣，手上布满老茧与细小的划痕，据传是出生于灯彩世家，一手做长明灯的手法出神入化。",sex="男",age=50,looks=20,showequip={},withCorpse=0},["25rwnpc15"]={id="25rwnpc15",dsc="他是侍奉在平遥公主身边的公公。",sex="男",age=55,looks=22,showequip={},withCorpse=0},["25rwnpc16"]={id="25rwnpc16",dsc="看打扮像是重光教众，手上拿着一柄重剑。",sex="男",age=28,looks=20,showequip={},withCorpse=0},["25rwnpc17"]={id="25rwnpc17",dsc="看打扮像是重光教众，手上拿着一双双钩。",sex="男",age=24,looks=20,showequip={},withCorpse=0},["25rwnpc18"]={id="25rwnpc18",dsc="看打扮像是重光教众，鬼鬼祟祟的样子，好像抱着一把斧头。",sex="男",age=26,looks=20,showequip={},withCorpse=0}}0000